DO $$ DECLARE d text; a integer; b integer; BEGIN d:=pg_get_functiondef('public.foreign_work_verify_rollback()'::regprocedure); a:=strpos(d,E' BEGIN\n INSERT INTO public.clients'); b:=strpos(d,E' INSERT INTO public.time_entries(project_id,installer_id,entry_date,hours,travel_hours,source,client_id,note) SELECT'); IF a=0 OR b<=a THEN RAISE EXCEPTION 'Unexpected fixture function'; END IF; d:=substr(d,1,a-1)||E' BEGIN\n INSERT INTO public.clients(name,customer_number,sandbox) VALUES(''TEST-FW-ROLLBACK'',''TEST-FW-ROLLBACK'',true) RETURNING id INTO c;\n INSERT INTO public.projects(name,ref,client_id,project_type,status,start_date,end_date,country,country_code,country_provenance,sandbox) VALUES(''TEST-FW-ROLLBACK'',''TEST-FW-ROLLBACK-''||gen_random_uuid(),c,''installation'',''open'',''2026-03-01'',''2026-03-15'',''Finland'',''FI'',''CONFIRMED'',true) RETURNING id INTO p;\n'||substr(d,b); EXECUTE d; END $$;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.foreign_work_days(date,date,uuid)'::regprocedure); IF strpos(d,'r.hours>0 AND r.country IS NOT NULL AND r.home IS NOT NULL AND r.project_id IS NOT NULL')=0 THEN RAISE EXCEPTION 'Unexpected day function'; END IF; d:=replace(d,'r.hours>0 AND r.country IS NOT NULL AND r.home IS NOT NULL AND r.project_id IS NOT NULL','r.hours>0 AND r.country IS NOT NULL AND r.home IS NOT NULL AND r.project_id IS NOT NULL AND r.country<>r.home'); EXECUTE d; END $$;